  "project_id": "a3a535793d3c4b6580af",
  "name": "fix_workspace_scoped_note_access",
  "query": "ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY;

CREATE POLICY "users can read their own memberships"
  ON public.memberships
  FOR SELECT
  TO authenticated
  USING ((select auth.uid()) = user_id);

DROP POLICY "members can read notes" ON public.notes;

CREATE POLICY "members can read notes"
  ON public.notes
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1
      FROM public.memberships AS m
      WHERE m.user_id = (select auth.uid())
        AND m.org_id = notes.org_id
    )
  );"
}

